using System.Collections.Generic;
using HarmonyLib;
using UnityEngine;
using Il2CppInterop.Runtime;
public static class CoopBossMechanics {
 static readonly List<GridPieceObj> Bosses=new List<GridPieceObj>();static readonly Vector3[] Targets=new Vector3[2];static readonly bool[] Marked=new bool[2];static readonly Shapes.Disc[] Rings=new Shapes.Disc[2];static float Clock=8,Telegraph;static bool Armed;static GridPieceInst Shooter;
 public static string Warning {get{return Armed?CoopLocalization.Text("Chefe marcou as posições — afastem-se das duas zonas!"):"";}}
 public static void Install(Harmony h){h.Patch(AccessTools.Method(typeof(GridPieceObj),"Init",new[]{typeof(GridPieceInst)}),postfix:new HarmonyMethod(typeof(CoopBossMechanics),nameof(Track)));}
 static void Track(GridPieceObj __instance){if(CoopMode.Enabled&&__instance.Inst!=null&&StatUtl.IsBoss(__instance.Inst.Type))Bosses.Add(__instance);}
 public static void Reset(){Bosses.Clear();Clock=8;Armed=false;for(int i=0;i<2;i++)if(Rings[i]!=null)Rings[i].gameObject.SetActive(false);}
 static float NextScan;
 static GridPieceInst VisibleBoss(){var camera=Camera.main;if(camera==null)return null;if(Time.unscaledTime>=NextScan){NextScan=Time.unscaledTime+1;var all=Resources.FindObjectsOfTypeAll(Il2CppType.Of<GridPieceObj>());for(int index=0;index<all.Length;index++){var obj=all[index].Cast<GridPieceObj>();if(obj.Inst!=null&&StatUtl.IsBoss(obj.Inst.Type)&&!Bosses.Contains(obj))Bosses.Add(obj);}}
  for(int i=Bosses.Count-1;i>=0;i--){var boss=Bosses[i];if(boss==null){Bosses.RemoveAt(i);continue;}if(!boss.gameObject.activeInHierarchy||boss.Inst.CurHealth<=0)continue;var view=camera.WorldToViewportPoint(boss.GetWorldCenterPos());if(view.z>0&&view.x>=0&&view.x<=1&&view.y>=0&&view.y<=1)return boss.Inst;}return null;}
 static void Arm(GridPieceInst shooter){Shooter=shooter;Armed=true;Telegraph=1.8f;for(int slot=0;slot<2;slot++){Marked[slot]=!CoopVitals.Life.Down(slot);if(!Marked[slot])continue;Targets[slot]=CoopCombat.Pos(CoopCombat.PlayerAt(slot));if(Rings[slot]==null){var obj=new GameObject("CoopBossWarning"+slot);Rings[slot]=obj.AddComponent(Il2CppType.Of<Shapes.Disc>()).Cast<Shapes.Disc>();Rings[slot].Type=Shapes.DiscType.Ring;Rings[slot].Radius=1.05f;Rings[slot].Thickness=0.08f;Rings[slot].Color=new Color(1,0.2f,0.15f,0.8f);}Rings[slot].transform.position=Targets[slot]+new Vector3(0,0,-1);Rings[slot].gameObject.SetActive(true);}}
 static void Fire(){try{if(Shooter==null)return;for(int slot=0;slot<2;slot++){if(CoopVitals.Life.Down(slot))continue;var player=CoopCombat.PlayerAt(slot);if(player==null)continue;bool hit=false;for(int zone=0;zone<2;zone++)if(Marked[zone]&&((Vector2)(CoopCombat.Pos(player)-Targets[zone])).sqrMagnitude<1.1025f)hit=true;if(hit){float damage=Mathf.Max(1,Mathf.Max(Shooter.GetArrowDamage(),Shooter.GetMeleeDamage()));if(slot==1)CoopCharacters.ForSecond(()=>{if(player.CanBeDamaged(PieceDmgType.kArrow))player.Damage(damage,PieceDmgType.kArrow);});else if(player.CanBeDamaged(PieceDmgType.kArrow))player.Damage(damage,PieceDmgType.kArrow);}}}finally{Armed=false;Clock=12;for(int i=0;i<2;i++)if(Rings[i]!=null)Rings[i].gameObject.SetActive(false);}}
 public static void Tick(){if(!CoopVitals.Active||CoopRoundStats.Complete){Reset();return;}if(GameMgr.I==null)return;if(GameMgr.I.CurState!=GameState.kPlaying){for(int i=0;i<2;i++)if(Rings[i]!=null)Rings[i].gameObject.SetActive(false);return;}if(!Armed){var shooter=VisibleBoss();if(shooter==null)return;Clock-=Time.unscaledDeltaTime;if(Clock<=0)Arm(shooter);}else{if(Shooter==null||Shooter.CurHealth<=0){Armed=false;Clock=8;for(int i=0;i<2;i++)if(Rings[i]!=null)Rings[i].gameObject.SetActive(false);return;}for(int i=0;i<2;i++)if(Rings[i]!=null)Rings[i].gameObject.SetActive(Marked[i]&&!CoopVitals.Down(i));Telegraph-=Time.unscaledDeltaTime;if(Telegraph<=0)Fire();}}
}

